class Solution {
public:
    int signFunc(int prod_sign){
        if(prod_sign == 0){
            return 1;
        }else{
            return -1;
        }
    }

    int arraySign(vector<int>& nums) {
        int prod_non_zero = 1;
        int neg_no = 0;
        for(int i=0; i<nums.size(); i++){
            if(nums[i] == 0){
                prod_non_zero = 0;
                break;
            }
            if(nums[i] < 0){
                neg_no++;
            }
        }

        if(prod_non_zero == 0){
            return 0;
        }else{
            return signFunc(neg_no%2);
        }

    }
};

