class Solution {
public:
    bool isPalindrome(int x) {
        if(x < 0){
            return false;
        }
        int num = x;
        long long rev_num = 0;
        while(num != 0){
            int digit = num % 10;
            rev_num = rev_num*10 + digit;
            num = num / 10;
        }
        if(rev_num == x){
            return true;
        }else{
            return false;
        }
    }
};

