happy-number.work:
class Solution {
private:
    // Helper function to calculate the sum of squared digits
    int getNext(int n) {
        int totalSum = 0;
        while (n > 0) {
            int digit = n % 10;
            totalSum += digit * digit;
            n /= 10;
        }
        return totalSum;
    }

public:
    bool isHappy(int n) {
        int slow = n;
        // Give the fast runner a head start of one step
        int fast = getNext(n);

        // Keep running until fast reaches 1, or they crash into each other
        while (fast != 1 && slow != fast) {
            // Slow runner takes one step
            slow = getNext(slow);
            // Fast runner takes two steps
            fast = getNext(getNext(fast));
        }

        // If the loop stopped because fast reached 1, it is a happy number
        return fast == 1;
    }
};

ugly-number.work:
class Solution {
public:
    bool isUgly(int n) {
        // A negative number or zero can never be an ugly number
        if (n <= 0) {
            return false;
        }

        // Keep dividing out the allowed prime factors: 2, 3, and 5
        while (n % 2 == 0) {
            n /= 2;
        }
        while (n % 3 == 0) {
            n /= 3;
        }
        while (n % 5 == 0) {
            n /= 5;
        }

        // If we successfully removed all 2s, 3s, and 5s, we should be left with exactly 1
        return n == 1;
    }
};

self-dividing-numbers.work:
class Solution {
private:
    bool checkDivide(int n){
        int temp = n;
        while (temp!=0){
            int digit = temp%10;
            if(digit == 0 || n%digit != 0){
                return false;
            }
            temp = temp/10;
        }

        return true;
    }

public:
    vector<int> selfDividingNumbers(int left, int right) {
        vector<int> ans;
        for(int i = left; i<=right; i++){
            bool res = checkDivide(i);
            if(res){
                ans.push_back(i);
            }
        }
        return ans;
    }
};

